      { id: 7, game_number: 7, title: "Population Simulator", description: "Manage population growth and limiting factors.", lesson: "Population Dynamics", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 8, game_number: 8, title: "Anatomy Labeler", description: "Label human body systems and organs correctly.", lesson: "Human Body Systems", base_reward: 100, coin_cost: 15, difficulty: "Medium" },
      { id: 9, game_number: 9, title: "Immune Response", description: "Learn how immune cells fight infections and disease.", lesson: "Immune System & Disease", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 10, game_number: 10, title: "Taxonomy Challenge", description: "Classify organisms using the binomial nomenclature system.", lesson: "Classification & Taxonomy", base_reward: 200, coin_cost: 25, difficulty: "Expert" },
    ],
    Chemistry: [
      { id: 11, game_number: 1, title: "Periodic Table Master", description: "Learn elements, symbols, and periodic trends.", lesson: "Atomic Structure & Periodic Table", base_reward: 50, coin_cost: 0, difficulty: "Easy" },
      { id: 12, game_number: 2, title: "Electron Configuration", description: "Fill electron shells with correct orbital arrangement.", lesson: "Electrons & Energy Levels", base_reward: 100, coin_cost: 15, difficulty: "Medium" },
      { id: 13, game_number: 3, title: "Bonding Builder", description: "Form ionic, covalent, and metallic bonds.", lesson: "Chemical Bonding", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
