      { id: 35, game_number: 5, title: "Weather Predictor", description: "Analyze weather patterns and atmospheric conditions.", lesson: "Weather & Atmosphere", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 36, game_number: 6, title: "Climate Modeler", description: "Simulate climate scenarios and predict changes.", lesson: "Climate & Climate Change", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 37, game_number: 7, title: "Conservation Hero", description: "Make decisions to protect endangered species and habitats.", lesson: "Biodiversity & Conservation", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 38, game_number: 8, title: "Pollution Fighter", description: "Identify pollution types and environmental solutions.", lesson: "Pollution & Environmental Issues", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 39, game_number: 9, title: "Renewable Energy", description: "Learn about solar, wind, and sustainable energy sources.", lesson: "Renewable & Sustainable Resources", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 40, game_number: 10, title: "Ecosystem Manager", description: "Balance human needs with ecosystem health.", lesson: "Human Impact & Sustainability", base_reward: 200, coin_cost: 25, difficulty: "Expert" },
    ],
    Economics: [
      { id: 41, game_number: 1, title: "Supply & Demand", description: "Balance markets and find equilibrium prices.", lesson: "Supply, Demand & Markets", base_reward: 50, coin_cost: 0, difficulty: "Easy" },
      { id: 42, game_number: 2, title: "Business Tycoon", description: "Run a virtual business with profit and loss.", lesson: "Business & Entrepreneurship", base_reward: 100, coin_cost: 15, difficulty: "Medium" },
      { id: 43, game_number: 3, title: "Budget Manager", description: "Create household and government budgets.", lesson: "Personal & Government Finance", base_reward: 100, coin_cost: 15, difficulty: "Medium" },
      { id: 44, game_number: 4, title: "Investment Trader", description: "Buy and sell stocks and build a portfolio.", lesson: "Stocks & Investments", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 45, game_number: 5, title: "GDP Calculator", description: "Measure economic growth and productivity.", lesson: "Macroeconomics & GDP", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 46, game_number: 6, title: "Inflation Monitor", description: "Manage inflation, unemployment, and interest rates.", lesson: "Inflation & Monetary Policy", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 47, game_number: 7, title: "Trade Navigator", description: "Understand international trade and tariffs.", lesson: "International Trade", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 48, game_number: 8, title: "Tax Planner", description: "Calculate taxes and optimize financial strategy.", lesson: "Taxation & Tax Planning", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 49, game_number: 9, title: "Labor Economics", description: "Understand wages, employment, and worker rights.", lesson: "Labor Economics", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 50, game_number: 10, title: "Economic Systems", description: "Compare capitalism, socialism, and mixed economies.", lesson: "Economic Systems & Theory", base_reward: 200, coin_cost: 25, difficulty: "Expert" },
    ],
    History: [
      { id: 51, game_number: 1, title: "Timeline Constructor", description: "Arrange historical events in correct order.", lesson: "Ancient Civilizations", base_reward: 50, coin_cost: 0, difficulty: "Easy" },
      { id: 52, game_number: 2, title: "Medieval Kingdoms", description: "Learn about feudalism and medieval society.", lesson: "Medieval Period", base_reward: 100, coin_cost: 15, difficulty: "Medium" },
