      { id: 56, game_number: 6, title: "Industrial Era", description: "Learn about industrialization and social changes.", lesson: "Industrial Revolution", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 57, game_number: 7, title: "World War Historian", description: "Study major conflicts and their impacts.", lesson: "20th Century Wars", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 58, game_number: 8, title: "Cold War Strategies", description: "Understand geopolitical tensions and diplomacy.", lesson: "Cold War Period", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 59, game_number: 9, title: "Modern History Map", description: "Trace contemporary historical movements and events.", lesson: "Modern History & Globalization", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 60, game_number: 10, title: "Historical Figures", description: "Match leaders and thinkers with their achievements.", lesson: "Key Historical Figures", base_reward: 200, coin_cost: 25, difficulty: "Expert" },
    ],
    "Human Geography": [
      { id: 61, game_number: 1, title: "Map Master", description: "Identify countries, capitals, and geographic features.", lesson: "World Geography & Maps", base_reward: 50, coin_cost: 0, difficulty: "Easy" },
      { id: 62, game_number: 2, title: "Culture Explorer", description: "Learn about different cultures and traditions worldwide.", lesson: "Cultural Geography", base_reward: 100, coin_cost: 15, difficulty: "Medium" },
      { id: 63, game_number: 3, title: "Population Analyzer", description: "Study population distribution and demographics.", lesson: "Population & Demographics", base_reward: 100, coin_cost: 15, difficulty: "Medium" },
      { id: 64, game_number: 4, title: "Urban Planner", description: "Design sustainable cities and urban spaces.", lesson: "Urban Geography", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 65, game_number: 5, title: "Economic Regions", description: "Understand global economic zones and trade.", lesson: "Economic Geography", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 66, game_number: 6, title: "Political Boundaries", description: "Learn geopolitics and international borders.", lesson: "Political Geography", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 67, game_number: 7, title: "Resource Manager", description: "Manage natural resources sustainably.", lesson: "Natural Resources & Environment", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 68, game_number: 8, title: "Migration Tracker", description: "Understand human migration and diaspora.", lesson: "Migration & Diaspora", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 69, game_number: 9, title: "Climate & Landscape", description: "Explore climate zones and landforms.", lesson: "Climate & Landforms", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 70, game_number: 10, title: "Development Compass", description: "Compare economic development across regions.", lesson: "Development & Inequality", base_reward: 200, coin_cost: 25, difficulty: "Expert" },
    ],
    Psychology: [
      { id: 71, game_number: 1, title: "Cognitive Bias Detector", description: "Identify common thinking patterns and biases.", lesson: "Introduction to Psychology", base_reward: 50, coin_cost: 0, difficulty: "Easy" },
      { id: 72, game_number: 2, title: "Memory Mastermind", description: "Learn and test different types of memory.", lesson: "Sensation & Perception", base_reward: 100, coin_cost: 15, difficulty: "Medium" },
      { id: 73, game_number: 3, title: "Learning Pathways", description: "Understand classical and operant conditioning.", lesson: "Learning & Conditioning", base_reward: 100, coin_cost: 15, difficulty: "Medium" },
      { id: 74, game_number: 4, title: "Motivation Motivator", description: "Explore needs, drives, and motivation theories.", lesson: "Motivation & Emotion", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 75, game_number: 5, title: "Personality Puzzle", description: "Learn personality theories and assessment.", lesson: "Personality & Development", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 76, game_number: 6, title: "Social Dynamics", description: "Understand group behavior and social influence.", lesson: "Social Psychology", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 77, game_number: 7, title: "Mental Health Guide", description: "Learn about disorders and mental wellness.", lesson: "Mental Health & Disorders", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 78, game_number: 8, title: "Therapy Techniques", description: "Understand psychological treatments and therapy.", lesson: "Therapies & Interventions", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 79, game_number: 9, title: "Neuroscience Quest", description: "Explore brain structure and neurotransmitters.", lesson: "Biopsychology & Neuroscience", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 80, game_number: 10, title: "Research Methods", description: "Learn experimental design and statistical analysis.", lesson: "Research Methods & Statistics", base_reward: 200, coin_cost: 25, difficulty: "Expert" },
    ],
  };

  const topicGames = gamesByTopic[selectedTopic] || [];

  // Game content library - maps game IDs to actual game data
  const gameContentLibrary = {
    1: {
      type: "matching",
      matchPairs: [
        { term: "Mitochondria", answer: "mitochondria", definition: "Powerhouse of the cell, responsible for energy production" },
        { term: "Nucleus", answer: "nucleus", definition: "Controls cell activities and contains genetic material" },
        { term: "Ribosome", answer: "ribosome", definition: "Site of protein synthesis" },
        { term: "Chloroplast", answer: "chloroplast", definition: "Performs photosynthesis in plant cells" },
        { term: "Golgi Apparatus", answer: "golgi", definition: "Modifies and packages proteins" },
      ],
    },
    2: {
      type: "quiz",
      questions: [
        {
          question: "What are the two main stages of photosynthesis?",
          options: ["Light reactions and dark reactions", "Oxidation and reduction", "Glycolysis and citric acid cycle", "Hydration and condensation"],
          correct: "Light reactions and dark reactions",
          explanation: "The light reactions occur in the thylakoids and the Calvin cycle (dark reactions) occurs in the stroma.",
        },
        {
          question: "In which organelle does photosynthesis primarily occur?",
          options: ["Mitochondria", "Chloroplast", "Nucleus", "Ribosome"],
          correct: "Chloroplast",
          explanation: "Chloroplasts contain chlorophyll and are the sites of photosynthesis.",
        },
        {
          question: "What is the primary product of the light reactions?",
          options: ["Glucose", "Oxygen and ATP", "Carbon dioxide", "Water"],
          correct: "Oxygen and ATP",
          explanation: "Light reactions produce ATP, NADPH, and release oxygen as a byproduct.",
        },
      ],
    },
    3: {
      type: "matching",
      matchPairs: [
        { term: "Natural Selection", answer: "selection", definition: "Process where organisms with favorable traits survive and reproduce" },
        { term: "Adaptation", answer: "adaptation", definition: "Trait that helps an organism survive in its environment" },
        { term: "Mutation", answer: "mutation", definition: "Random change in DNA that creates genetic variation" },
        { term: "Speciation", answer: "speciation", definition: "Process where new species evolve from a common ancestor" },
      ],
    },
    11: {
      type: "quiz",
      questions: [
        {
          question: "What is the atomic number of Carbon?",
          options: ["4", "6", "8", "12"],
          correct: "6",
          explanation: "Carbon has 6 protons, giving it an atomic number of 6.",
        },
        {
          question: "Which period does Oxygen belong to in the periodic table?",
          options: ["Period 1", "Period 2", "Period 3", "Period 4"],
          correct: "Period 2",
          explanation: "Oxygen is in the 2nd period of the periodic table.",
        },
        {
          question: "How many valence electrons does Chlorine have?",
          options: ["5", "6", "7", "8"],
          correct: "7",
          explanation: "Chlorine is in Group 17 and has 7 valence electrons.",
        },
      ],
    },
    21: {
      type: "quiz",
      questions: [
        {
          question: "Which of Newton's laws states that force equals mass times acceleration?",
          options: ["First Law", "Second Law", "Third Law", "Law of Gravitation"],
          correct: "Second Law",
          explanation: "F=ma is Newton's Second Law of Motion.",
        },
        {
          question: "What happens to an object in motion if no net force acts on it?",
          options: ["It accelerates", "It continues moving at constant velocity", "It stops immediately", "Its mass increases"],
          correct: "It continues moving at constant velocity",
          explanation: "This is Newton's First Law - an object in motion stays in motion unless acted upon by a force.",
        },
      ],
    },
    31: {
      type: "matching",
      matchPairs: [
        { term: "Tropical Rainforest", answer: "rainforest", definition: "Warm, wet biome near the equator with high biodiversity" },
        { term: "Desert", answer: "desert", definition: "Arid biome with very low precipitation and sparse vegetation" },
        { term: "Taiga", answer: "taiga", definition: "Cold biome with coniferous forests and long winters" },
        { term: "Tundra", answer: "tundra", definition: "Frozen biome with permafrost and minimal vegetation" },
      ],
    },
    41: {
      type: "quiz",
      questions: [
        {
          question: "What happens to the equilibrium price when demand increases but supply remains constant?",
          options: ["Price decreases", "Price increases", "Price stays the same", "Supply must increase"],
          correct: "Price increases",
          explanation: "When demand increases with constant supply, there's a shortage, driving prices up.",
        },
        {
          question: "Which factor shifts the supply curve?",
          options: ["Consumer preferences", "Production technology", "Consumer income", "Competitor prices"],
          correct: "Production technology",
          explanation: "Improved technology can increase supply by making production more efficient.",
        },
      ],
    },
    51: {
      type: "puzzle",
      items: [
        { label: "Ancient Egypt", order: 1 },
        { label: "Roman Empire", order: 2 },
        { label: "Medieval Period", order: 3 },
        { label: "Renaissance", order: 4 },
        { label: "Industrial Revolution", order: 5 },
      ],
    },
    61: {
      type: "quiz",
      questions: [
        {
          question: "Which country is the largest by land area?",
          options: ["Canada", "USA", "Russia", "Australia"],
          correct: "Russia",
          explanation: "Russia is the largest country in the world by total land area.",
        },
        {
          question: "What is the capital of France?",
          options: ["Lyon", "Paris", "Marseille", "Toulouse"],
          correct: "Paris",
          explanation: "Paris is the capital and largest city of France.",
        },
      ],
    },
    71: {
      type: "quiz",
      questions: [
        {
          question: "What is a cognitive bias?",
          options: ["A type of mental disorder", "A systematic error in thinking and judgment", "An inability to learn", "A genetic disorder"],
          correct: "A systematic error in thinking and judgment",
          explanation: "Cognitive biases are mental shortcuts that can lead to systematic errors in judgment.",
        },
        {
          question: "Which of the following is an example of confirmation bias?",
          options: ["Seeking information that confirms existing beliefs", "Fear of missing out", "Being overly confident", "Inability to make decisions"],
          correct: "Seeking information that confirms existing beliefs",
          explanation: "Confirmation bias is the tendency to search for information that confirms what we already believe.",
        },
      ],
    },
  };

  const getGameContent = (gameId) => {
    return gameContentLibrary[gameId] || { type: "quiz", questions: [] };
  };

  const playGame = (game) => {
    // Check if game requires coins
    if (game.coin_cost > 0) {
      if (playerCoins < game.coin_cost) {
        alert(`❌ Not enough coins! You need ${game.coin_cost} coins but only have ${playerCoins}`);
        return;
      }
    }

    // Load game content
    const gameContent = getGameContent(game.id);
    setActiveGame(game);
    setGameType(gameContent.type);
  };

  const handleGameComplete = (scoreEarned) => {
    if (!activeGame) return;

    // Deduct coins if paid game
    let newCoins = playerCoins;
    if (activeGame.coin_cost > 0) {
      newCoins = playerCoins - activeGame.coin_cost;
    }

    // Add reward coins
    newCoins += activeGame.base_reward;
    setPlayerCoins(newCoins);

    // Update user
    if (user) {
      const updatedUser = { ...user, coins: newCoins };
      localStorage.setItem("user", JSON.stringify(updatedUser));
      setUser(updatedUser);
    }

    // Track progress
    setProgress((prev) => ({
      ...prev,
      [activeGame.id]: (prev[activeGame.id] || 0) + 1,
    }));

    // Notify parent
    if (onGameWin) onGameWin(activeGame.id, activeGame.base_reward);

    // Show completion modal
    alert(`🎉 Great job! You earned ${activeGame.base_reward} coins!`);
    setActiveGame(null);
  };

  const handleExitGame = () => {
    if (window.confirm("Are you sure you want to exit? Your progress will not be saved.")) {
      setActiveGame(null);
    }
  };

  if (isLoading) {
    return <div style={{ padding: "40px", textAlign: "center", color: "white", background: "#0f172a", minHeight: "100vh" }}>
      <h1>Loading games...</h1>
    </div>;
  }

  if (!user) {
    return <div style={{ padding: "40px", textAlign: "center", color: "white", background: "#0f172a", minHeight: "100vh" }}>
      <h1>⚠️ Please log in to play games</h1>
      <p>Redirect to login...</p>
    </div>;
  }

  return (
    <section style={{ padding: "40px 20px", minHeight: "100vh", background: "#0f172a", color: "white" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "10px" }}>
        <h1 style={{ textAlign: "center", flex: 1, fontSize: "32px", margin: 0 }}>🎮 Games by Subject</h1>
        <div style={{ fontSize: "18px", fontWeight: "600", color: "#fbbf24", marginRight: "20px" }}>
          💰 {playerCoins} Coins
        </div>
      </div>
      <p style={{ textAlign: "center", marginBottom: "40px", fontSize: "14px", color: "#cbd5e1" }}>Welcome {user?.firstName || "Player"}! Play games to earn coins and master each topic!</p>

      {/* Topic Selection */}
      <div style={{ marginBottom: "32px", display: "flex", gap: "12px", flexWrap: "wrap", justifyContent: "center" }}>
        {Object.keys(gamesByTopic).map((topic) => (
          <button
            key={topic}
            onClick={() => setSelectedTopic(topic)}
            style={{
              padding: "10px 20px",
              borderRadius: "8px",
              border: selectedTopic === topic ? "2px solid #06b6d4" : "2px solid #4b5563",
              backgroundColor: selectedTopic === topic ? "#06b6d4" : "transparent",
              color: "white",
              cursor: "pointer",
              fontSize: "14px",
              fontWeight: selectedTopic === topic ? "700" : "400",
              transition: "all 0.3s ease",
            }}
          >
            {topic}
          </button>
        ))}
      </div>

      {/* Games Grid */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))", gap: "20px", maxWidth: "1400px", margin: "0 auto" }}>
        {topicGames.map((game) => {
          const isFree = game.coin_cost === 0;
          const canPlay = isFree || playerCoins >= game.coin_cost;

          return (
            <div key={game.id} style={{ 
              padding: "20px", 
              borderRadius: "12px", 
              border: isFree ? "2px solid #10b981" : canPlay ? "1px solid rgba(99, 102, 241, 0.3)" : "1px solid rgba(239, 68, 68, 0.3)",
              backgroundColor: isFree ? "rgba(16, 185, 129, 0.1)" : canPlay ? "rgba(30, 41, 59, 0.6)" : "rgba(127, 29, 29, 0.2)",
            }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "start", marginBottom: "8px" }}>
                <div>
                  <h3 style={{ margin: "0 0 8px 0", fontSize: "18px", color: "#ffffff" }}>{game.title}</h3>
                  <p style={{ fontSize: "12px", color: "#94a3b8", margin: "0 0 4px 0" }}>Lesson: {game.lesson}</p>
                </div>
                <div style={{
                  padding: "4px 12px",
                  borderRadius: "4px",
                  fontSize: "11px",
                  fontWeight: "600",
                  backgroundColor: isFree ? "#10b981" : game.difficulty === "Easy" ? "#06b6d4" : game.difficulty === "Medium" ? "#f59e0b" : game.difficulty === "Hard" ? "#ef4444" : "#a855f7",
                  color: "white",
                  whiteSpace: "nowrap"
                }}>
                  {isFree ? "FREE" : game.difficulty}
                </div>
              </div>

              <p style={{ fontSize: "14px", color: "#cbd5e1", margin: "0 0 16px 0", minHeight: "40px" }}>{game.description}</p>

              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: "16px", gap: "12px", fontSize: "13px" }}>
                <div style={{ display: "flex", gap: "12px" }}>
                  {game.coin_cost > 0 && (
                    <div style={{ color: "#fbbf24", fontWeight: "600" }}>
                      💰 {game.coin_cost} to play
                    </div>
                  )}
                  <div style={{ color: "#10b981", fontWeight: "600" }}>
                    ⭐ +{game.base_reward} coins
                  </div>
                </div>
                <button
                  onClick={() => playGame(game)}
                  disabled={!canPlay}
                  style={{
                    padding: "8px 16px",
                    borderRadius: "6px",
                    border: "none",
                    backgroundColor: canPlay ? "#6366f1" : "#6b7280",
                    color: "white",
                    cursor: canPlay ? "pointer" : "not-allowed",
                    fontSize: "14px",
                    fontWeight: "600",
                    transition: "all 0.3s ease",
                    opacity: canPlay ? 1 : 0.6,
                  }}
                  onMouseEnter={(e) => {
                    if (canPlay) {
                      e.target.style.backgroundColor = "#4f46e5";
                    }
                  }}
                  onMouseLeave={(e) => {
                    if (canPlay) {
                      e.target.style.backgroundColor = "#6366f1";
                    }
                  }}
                >
                  {!canPlay ? "🔒 Locked" : progress[game.id] ? `Played ${progress[game.id]}x` : "Play"}
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
}

export default Games;
